CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, applied_utc TEXT NOT NULL);
INSERT INTO schema_migrations VALUES(1, '2020-01-01T00:00:00.000Z');
CREATE TABLE sessions(session_id TEXT PRIMARY KEY,created_utc TEXT NOT NULL,participant_label TEXT,record_type TEXT,profile_id TEXT,profile_version INTEGER,status TEXT NOT NULL,reveal_policy TEXT,recovery_state TEXT,manifest_json TEXT,hidden_objective TEXT,participant_target TEXT);
CREATE TABLE trials(trial_id TEXT PRIMARY KEY,session_id TEXT NOT NULL REFERENCES sessions(session_id),trial_seq INTEGER NOT NULL,trial_type TEXT,config_json TEXT,state TEXT);
CREATE TABLE session_commitments(session_id TEXT PRIMARY KEY REFERENCES sessions(session_id),canonical_config TEXT NOT NULL,config_hash TEXT NOT NULL,committed_utc TEXT NOT NULL);
CREATE TABLE evidence_events(session_id TEXT NOT NULL REFERENCES sessions(session_id),seq INTEGER NOT NULL,event_id TEXT NOT NULL,event_type TEXT NOT NULL,occurred_utc TEXT NOT NULL,monotonic_ns TEXT NOT NULL,payload_json TEXT NOT NULL,previous_hash TEXT NOT NULL,event_hash TEXT NOT NULL,PRIMARY KEY(session_id,seq),UNIQUE(event_id));
CREATE TABLE machine_outputs(session_id TEXT NOT NULL REFERENCES sessions(session_id),trial_id TEXT,output_seq INTEGER NOT NULL,generated_utc TEXT NOT NULL,monotonic_ns TEXT NOT NULL,value_json TEXT NOT NULL,region TEXT,record_hash TEXT NOT NULL,PRIMARY KEY(session_id,output_seq));
CREATE TABLE raw_report_drafts(session_id TEXT PRIMARY KEY REFERENCES sessions(session_id),saved_utc TEXT NOT NULL,payload_json TEXT NOT NULL);
CREATE TABLE raw_reports_locked(session_id TEXT PRIMARY KEY REFERENCES sessions(session_id),locked_utc TEXT NOT NULL,payload_json TEXT NOT NULL,lock_hash TEXT NOT NULL,schema_version TEXT NOT NULL);
CREATE TABLE late_annotations(id INTEGER PRIMARY KEY AUTOINCREMENT,session_id TEXT NOT NULL REFERENCES sessions(session_id),created_utc TEXT NOT NULL,kind TEXT NOT NULL,payload_json TEXT NOT NULL,annotation_hash TEXT NOT NULL);
CREATE TABLE experiment_profiles(profile_id TEXT PRIMARY KEY,name TEXT NOT NULL,provenance TEXT);
CREATE TABLE profile_versions(profile_id TEXT NOT NULL REFERENCES experiment_profiles(profile_id),version INTEGER NOT NULL,config_json TEXT NOT NULL,config_hash TEXT NOT NULL,created_utc TEXT NOT NULL,PRIMARY KEY(profile_id,version));
CREATE TABLE audio_recipes(recipe_id TEXT PRIMARY KEY,provenance TEXT);
CREATE TABLE audio_recipe_versions(recipe_id TEXT NOT NULL REFERENCES audio_recipes(recipe_id),version INTEGER NOT NULL,config_json TEXT NOT NULL,config_hash TEXT NOT NULL,created_utc TEXT NOT NULL,PRIMARY KEY(recipe_id,version));
CREATE TABLE calibrations(calibration_id TEXT PRIMARY KEY,created_utc TEXT NOT NULL,provider TEXT,provider_version TEXT,sample_count INTEGER,counts_json TEXT,statistics_json TEXT,metadata_json TEXT,result_hash TEXT,integrity_status TEXT);
CREATE TABLE analyses(session_id TEXT PRIMARY KEY REFERENCES sessions(session_id),analysis_version TEXT,input_hash TEXT,payload_json TEXT,created_utc TEXT);
CREATE TABLE integrity_metadata(session_id TEXT PRIMARY KEY REFERENCES sessions(session_id),verified_utc TEXT,valid INTEGER,details_json TEXT);
CREATE TABLE backups(backup_id TEXT PRIMARY KEY,created_utc TEXT NOT NULL,path TEXT NOT NULL,sha256 TEXT NOT NULL,verified INTEGER NOT NULL);
